      "tagText": "वयाचे गुणोत्तर",
      "question": "दोन भावांच्या आजच्या वयांचे गुणोत्तर 3:4 आहे. 6 वर्षांनंतर त्यांच्या वयांचे गुणोत्तर 4:5 होईल. तर मोठ्या भावाचे आजचे वय किती?",
